package com.univmar.project.api; import com.univmar.common.api.*; import com.univmar.project.ProjectService; import com.univmar.project.api.ProjectDtos.*; import com.univmar.project.domain.ProjectStatus; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid; import java.util.*; import org.springframework.data.domain.Pageable; import org.springframework.data.web.PageableDefault; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/projects") public class ProjectController{private final ProjectService s;public ProjectController(ProjectService s){this.s=s;}@GetMapping public ApiResponse<ProjectPage> list(@RequestParam(required=false)String search,@RequestParam(required=false)UUID customerId,@RequestParam(required=false)ProjectStatus status,@PageableDefault(size=20,sort="name")Pageable p,HttpServletRequest r){return ok(s.list(search,customerId,status,p),r);}@PostMapping public ResponseEntity<ApiResponse<ProjectResponse>> create(@Valid @RequestBody ProjectInput i,HttpServletRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ok(s.create(i),r));}@GetMapping("/{id}") public ApiResponse<ProjectResponse> detail(@PathVariable UUID id,HttpServletRequest r){return ok(s.detail(id),r);}@PutMapping("/{id}") public ApiResponse<ProjectResponse> update(@PathVariable UUID id,@Valid @RequestBody ProjectInput i,HttpServletRequest r){return ok(s.update(id,i),r);}private<T>ApiResponse<T>ok(T x,HttpServletRequest r){return ApiResponse.of(x,(String)r.getAttribute(RequestIdFilter.REQUEST_ID_ATTRIBUTE));}}
